{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        raise ValueError("Budget out of range")
    allocations = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_ratio = float('-inf')
        best_idx = None
        for i in range(n):
            if allocations[i] < segments[i]['capacity']:
                ratio = segments[i]['importance'] / (allocations[i] + 1)
                if ratio > best_ratio or (ratio == best_ratio and (best_idx is None or i < best_idx)):
                    best_ratio = ratio
                    best_idx = i
        if best_idx is None:
            break
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    total = sum(allocations)
    return {"allocations": allocations, "by_name": by_name, "total": total}"
}
